def prepare_mask(mask_path):
    """
    Converts Black/White mask to Transparent/Opaque RGBA for OpenAI API.
    Black (Lips) -> Transparent (Alpha 0) -> Area to be edited
    White (Skin) -> Opaque (Alpha 255) -> Area to keep original
    """
    print(f"Preparing edit mask from: {mask_path}")
    with Image.open(mask_path).convert("L") as mask:
        w, h = mask.size
        # Create a white background RGBA image
        new_mask = Image.new("RGBA", (w, h), (255, 255, 255, 255))
        
        for y in range(h):
            for x in range(w):
                value = mask.getpixel((x, y))
                if value < 100:  # The black area detected as lips
                    new_mask.putpixel((x, y), (255, 255, 255, 0)) # Transparent
                else:
                    new_mask.putpixel((x, y), (255, 255, 255, 255)) # Opaque
        
        new_path = os.path.splitext(mask_path)[0] + "_lip_editmask.png"
        new_mask.save(new_path, "PNG")
    return new_path

def convert_image_to_rgba(image_path):
    with Image.open(image_path) as img:
        img = img.convert("RGBA")
        new_path = os.path.splitext(image_path)[0] + "_rgba_temp.png"
        img.save(new_path, "PNG")
    return new_path
