import base64
import os
from PIL import Image
import requests
from openai import OpenAI

def change_lip_color(image_path, mask_path, new_color, output_path):
    client = OpenAI(api_key=API_KEY)
    image_temp = None
    mask_temp = None

    try:
        image_temp = convert_image_to_rgba(image_path)
        mask_temp = prepare_mask(mask_path)

        print(f"\nSending Lip Edit request: {new_color}...")

        with open(image_temp, "rb") as img_file, open(mask_temp, "rb") as mask_file:
            response = client.images.edit(
                model="gpt-image-2",   # or "gpt-image-1.5" if available
                image=img_file,
                mask=mask_file,

                prompt = (
    "Change ONLY the color of the lips inside the masked area to matte soft pink lipstick. "
    "Do NOT change anything else in the image. "
    "Keep the skin, teeth, eyes, hair, lighting, shadows, texture, background and all other details 100% identical to the original photo. "
    "Photorealistic, natural blend only on the lips, no other modifications."
),
                size="1024x1024",
                # DO NOT pass response_format for gpt-image-1
            )


        # GPT Image models return b64_json by default
        b64_data = response.data[0].b64_json
        img_data = base64.b64decode(b64_data)

        with open(output_path, "wb") as f:
            f.write(img_data)

        print(f"✅ Success! Saved to: {output_path}")
        return output_path

    except Exception as e:
        print(f"❌ Error: {e}")
        import traceback
        traceback.print_exc()
        return None
    finally:
        # Cleanup temp files
        for f in [image_temp, mask_temp]:
            if f and os.path.exists(f):
                try:
                    os.remove(f)
                except:
                    pass


